CREATE TABLE IF NOT EXISTS gis_phase338_spatial_candidates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_name TEXT, target_name TEXT, source_state_code TEXT, target_state_code TEXT, name_similarity DOUBLE PRECISION, state_match BOOLEAN, bbox_overlap DOUBLE PRECISION, centroid_distance_km DOUBLE PRECISION, spatial_score DOUBLE PRECISION, candidate_score DOUBLE PRECISION, decision TEXT NOT NULL DEFAULT 'REVIEW', evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id,target_feature_id));